{
  "candidates": [
    {
      "explanation": "Pipeline-aware conservative relaxation: reduce orders when pipeline is high relative to recent demand, but never cut so much that downstream backlog risk increases. Small coordinated corrections across nodes.",
      "rules": [
        {
          "when": "pipeline > 3 * recent and backlog < 2",
          "delta": "-min(2, max(0, (pipeline - 3 * recent) / 4))"
        },
        {
          "when": "pipeline > 2 * recent and backlog >= 2",
          "delta": "-1"
        },
        {
          "when": "pipeline < recent and backlog > 0",
          "delta": "min(2, max(0, (recent - pipeline) / 2))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Backlog-sensitive smoothing: increase orders when backlog is high and pipeline is low, but avoid over-ordering when pipeline already covers demand. Downstream service protected by limiting cuts.",
      "rules": [
        {
          "when": "backlog > 2 * recent and pipeline < recent",
          "delta": "min(3, max(0, backlog / 2 - pipeline))"
        },
        {
          "when": "backlog > 0 and pipeline < 1.5 * recent",
          "delta": "min(1, max(0, backlog / 3))"
        },
        {
          "when": "pipeline > 2.5 * recent and backlog == 0",
          "delta": "-min(2, max(0, (pipeline - 2.5 * recent) / 3))"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Growth-adaptive damping: when recent demand exceeds baseline, slightly increase orders to avoid stockouts; when pipeline is excessive relative to growth, reduce cautiously. Keeps corrections small and coordinated.",
      "rules": [
        {
          "when": "growth > 1.2 and pipeline < recent and backlog > 0",
          "delta": "min(2, max(0, (growth - 1) * recent - pipeline))"
        },
        {
          "when": "growth < 0.8 and pipeline > 2 * recent",
          "delta": "-min(2, max(0, (pipeline - 2 * recent) / 2))"
        },
        {
          "when": "pipeline > 3 * recent and backlog == 0",
          "delta": "-1"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    }
  ]
}
